const newBooking = {
    url: 'https://restful-booker.herokuapp.com/booking',
    method: 'POST',
    header: {
        'Content-Type': 'application/json'
    },
    body: {
        mode: 'raw',
        raw: JSON.stringify({
            "firstname": "Oceane",
            "lastname": "Kilback",
            "totalprice": 420,
            "depositpaid": true,
            "bookingdates": {
                "checkin": "2025-01-20",
                "checkout": "2025-01-28"
            },
            "additionalneeds": "Computer"
        })
    }
}

pm.sendRequest(newBooking, (err, res) => {
    if (err) {
        console.error("Request failed:", err);
        return;
    }
    if (res) {
        let tempResp = res.json();
        booking_id_new = tempResp.bookingid;
        console.log("New Booking ID:", booking_id_new);
        pm.environment.set("booking_id_new", booking_id_new);
        pm.environment.set("tempFirstname", tempResp.booking.firstname);
        pm.environment.set("tempLastname", tempResp.booking.lastname);
        pm.environment.set("tempTotalprice", tempResp.booking.totalprice);
        pm.environment.set("tempDepositpaid", tempResp.booking.depositpaid);
        pm.environment.set("tempCheckin", tempResp.booking.bookingdates.checkin);
        pm.environment.set("tempCheckout", tempResp.booking.bookingdates.checkout);
